pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address burner, uint256 amount) public {
        vm.assume(burner != address(0));
        vm.assume(amount > 0 && amount <= 1e30);
        // Mint some tokens to the burner so we can burn
        c.mintSynth(burner, amount);
        // Transfer to address(this) so we can call burn from this contract
        vm.prank(burner);
        c.transfer(address(this), amount);
        // Now call burn, which internally calls _burn
        c.burn(amount);
        // The rule: totalSupply must equal the sum of all token balances.
        // We can check by reading balanceOf of the burner and our address.
        uint256 totalBalances = c.balanceOf(burner) + c.balanceOf(address(this)) + c.balanceOf(address(0));
        assertTrue(c.totalSupply() == totalBalances, "totalSupply != sum of balances");
    }
}

