pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(
        address user1,
        address user2,
        uint256 amount1,
        uint256 amount2
    ) public {
        // Bound amounts to avoid overflow
        amount1 = bound(amount1, 1, 1e24);
        amount2 = bound(amount2, 1, 1e24);

        // Ensure users are distinct and not zero
        vm.assume(user1 != address(0) && user2 != address(0) && user1 != user2);

        // Simulate two mintSynth calls by different pools (using prank to impersonate)
        // First mintSynth by user1 as pool
        vm.prank(user1);
        c.mintSynth(user1, amount1);

        // Record LP balance after first call
        uint256 lpBalanceAfterFirst = c.getmapAddress_LPBalance(user1);

        // Second mintSynth by user2 as pool
        vm.prank(user2);
        c.mintSynth(user2, amount2);

        // Call allowance to trigger the final check
        c.allowance(user1, user2);

        // General rule: After all operations, the sum of LP balances across all pools
        // must equal the sum of lpUnits added in each mintSynth call.
        // Since the bug adds an extra 1 to debt but not to LP balance, the ratio
        // in burnSynth will be affected, but we can test the invariant that
        // the LP balance for any pool cannot exceed the original LP balance
        // plus the lpUnits calculated for that pool's mintSynth call.

        // For user1 (first call): lpUnits = _getAddedLPAmount(user1) which was 0 initially
        // So user1's LP balance should be 0 + amount1 (since first mint has no previous LP)
        // Actually, let's check a simpler invariant:
        // The mapSynth_LPBalance for any pool must be >= its recorded debt ratio

        uint256 finalLPBalance1 = c.getmapAddress_LPBalance(user1);
        uint256 finalDebt1 = c.getmapAddress_LPDebt(user1);

        // For the reference contract: LP balance * (total supply / debt) should be conserved
        // But a simpler rule: LP balance cannot exceed the amount of LP tokens minted
        // which equals the lpUnits from _getAddedLPAmount (which is balanceOf(this) - previous)
        // Since we don't have access to internal state, use the fact that
        // after one mintSynth, LP balance equals the lpUnits calculated, which is
        // balanceOf(this) - previous LP balance (which was 0). So LP balance = balanceOf(this).
        // balanceOf(this) is public, so we can read it.

        uint256 balanceOfC = c.balanceOf(address(c));

        // The invariant: For user1, mapSynth_LPBalance[user1] must be <= balanceOfC
        // (since the LP balance cannot exceed the total LP tokens the contract holds)
        assertTrue(finalLPBalance1 <= balanceOfC, "LP balance exceeds total LP tokens");
    }
}

