pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address pool1, address pool2, uint256 amount) public {
        vm.assume(pool1 != address(0) && pool2 != address(0) && pool1 != pool2);
        vm.assume(amount > 0 && amount < 1e30);

        // Simulate adding LP tokens to contract via mint (we can't call Pool.mint directly, so we use transfer)
        // Instead, we'll just call allowance to trigger the view, and check the invariant
        uint256 oldBalance = c.balanceOf(address(this));
        uint256 oldTotalSupply = c.totalSupply();
        uint256 oldMapSum = c.getmapAddress_LPBalance(pool1) + c.getmapAddress_LPBalance(pool2);

        // Call allowance (the public endpoint specified)
        c.allowance(pool1, pool2);

        // After allowance, the sum of mapSynth_LPBalance should be <= oldMapSum + (any new LP tokens received)
        // Since allowance doesn't change state, the sum must remain the same
        uint256 newMapSum = c.getmapAddress_LPBalance(pool1) + c.getmapAddress_LPBalance(pool2);

        // The invariant: if we call allowance before and after, the map sum shouldn't change
        // because allowance is a pure view function (doesn't modify state)
        bool unchanged = (oldMapSum == newMapSum);
        assertTrue(unchanged, "mapSynth_LPBalance sum changed after allowance call");
    }
}

