contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(address(this), address(this)); 
    }

    function testFuzz_property(address caller, address spender, uint256 amount, address pool) public {
        // Bound amount to avoid overflow
        vm.assume(amount < 10**30);

        // First, we need to set up the pool address properly - in this simplified test we'll use address(this) as pool
        address testPool = address(this);

        // Simulate the scenario: mint some synths to the contract and set up LP balance/debt
